import fs from 'node:fs';

const path = 'random-dice-game-33.html';
let src = fs.readFileSync(path, 'utf8');
let changes = 0;

function replaceOnce(needle, replacement, label) {
  if (!src.includes(needle)) throw new Error(`Missing source marker for ${label}`);
  src = src.replace(needle, replacement);
  changes++;
}

function replaceLine(fnName, replacement) {
  const re = new RegExp(`^  function ${fnName}\\(.*$`, 'm');
  const m = src.match(re);
  if (!m) throw new Error(`Missing one-line function ${fnName}`);
  src = src.replace(re, replacement);
  changes++;
}

