replaceLine('canonTickTile', "  function canonTickTile(idx,die,d,dt,fromMask=false){if(!fromMask&&die.canon&&die.canon.maskPending){die.canon.maskPending.t-=dt;if(die.canon.maskPending.t<=0)canonFinishJokerMask(die);return true;}if(!fromMask&&die.canon&&die.canon.mask)return canonMaskedTick(idx,die,dt);const k=d.special&&d.special.kind;if(k==='canonLight'){canonLightPulse(idx,die,dt);return true;}if(k==='canonMine'){canonTickMine(idx,die,dt);return true;}if(k==='canonGrowth')return canonTickGrowth(idx,die,dt);if(k==='canonSnowfall')return canonTickSnowfall(idx,die,dt);if(k==='canonSkyhorn')return canonTickSkyhorn(idx,die,dt);if(k==='canonLaser'){die.sinceLastShot+=dt;if(die.sinceLastShot>=canonAttackInterval(die,canonC(die)>=7?.60:canonC(die)>=3?.65:.70)){die.sinceLastShot=0;const t=canonFront();if(t){const opened=fromMask&&canonBeginCopiedAction(die);canonFireSimple(die,t,8,'special',{});if(opened)canonEndCopiedAction(die);const c=canonC(die),p=canonP(die),gain=(c>=7?.11:c>=5?.10:c>=2?.09:.08)*(p>=7?1.10:1);die.canon.laserGauge=Math.min(1,(die.canon.laserGauge||0)+gain);}}return true;}if(k==='canonMarksman'&&die.canon.marksmanBusy)return true;if(k==='canonRelentlessMace'){if(die.canon.maceBusyT>0){die.canon.maceBusyT=Math.max(0,die.canon.maceBusyT-dt);return true;}if(die.canon.maceSwingActive)return true;}return false;}");

