replaceLine('canonFireMarksman', "  function canonFireMarksman(die,list){const c=canonC(die),p=canonP(die),cap=p>=7?4:p>=5?3:p>=3?2:1,raw=c>=7?37:c>=5?33:c>=3?29:c>=2?26:24,head=c>=7?.22:c>=6?.18:c>=5?.15:c>=4?.12:0,pen=c>=7?.20:c>=6?.16:c>=5?.12:c>=4?.08:c>=3?.05:0,scan=c>=7?.45:c>=6?.52:c>=2?.60:.65,inter=c>=7?.09:c>=6?.10:c>=5?.11:.12;let pool=list.slice(),lane=null;if(state.zombieMode&&c>=6){const lanes=[0,1,2,3,4].map(l=>({l,hp:pool.filter(e=>e.lane===l).reduce((s,e)=>s+e.hp,0)})).filter(x=>x.hp>0);if(lanes.length){let roll=Math.random()*lanes.reduce((s,x)=>s+x.hp,0);lane=lanes[0].l;for(const x of lanes){roll-=x.hp;if(roll<=0){lane=x.l;break;}}pool=pool.filter(e=>e.lane===lane);}}const locks=[];while(pool.length&&locks.length<cap){const n=Math.floor(Math.random()*pool.length);locks.push(pool.splice(n,1)[0]);}if(!locks.length)return;die.canon.marksmanBusy=true;state.canonMarksmanVolleys=state.canonMarksmanVolleys||[];state.canonMarksmanVolleys.push({die,c,p,cap,raw,head,pen,scan,inter,lane,locks:locks.map(canonEnemyId),t:0,phase:'scan',shotT:0,index:0,follow:Math.max(0,cap-locks.length),followIndex:0});}");

