// ---------- Padlock PvE ----------
replaceLine('canonApplyPadlockMerge', "  function canonApplyPadlockMerge(die){const c=canonC(die),p=canonP(die),list=aliveEnemies();if(!list.length)return;const primary=canonFront(list);if(!primary)return;let normalDur=(c>=7?3.5:c>=6?3.1:c>=5?2.8:c>=3?2.5:c>=2?2.3:2);if(p>=3)normalDur+=.15;if(p>=7)normalDur+=.20;normalDur*=canonPotency(die);const bossDelay=c>=7?1.8:c>=6?1.5:c>=5?1.35:c>=3?1.15:c>=2?1:.8;if(primary.isBoss){if(primary.skills)primary.skills.forEach(s=>s.cd+=bossDelay);}else{canonState(primary).sealedT=Math.max(canonState(primary).sealedT||0,normalDur);fx('padlockSeal',enemyRenderPos(primary),{dur:.55});}let secondaryChance=c>=7?1:c>=6?.40:c>=5?.35:c>=4?.25:0;if(p>=5&&c<7)secondaryChance+=.05;if(secondaryChance&&Math.random()<Math.min(1,secondaryChance+canonInsight(die))){const other=list.filter(e=>e!==primary)[0];if(other){let secDur=c>=7?1.8:c>=6?1.8:c>=5?1.7:1.4;if(p>=7)secDur+=.15;if(c>=7&&p>=5)secDur+=.10;if(other.isBoss&&other.skills)other.skills.forEach(s=>s.cd+=bossDelay*.4);else{canonState(other).sealedT=Math.max(canonState(other).sealedT||0,secDur*canonPotency(die));fx('padlockSeal',enemyRenderPos(other),{dur:.45});}}}}");

// ---------- Golden Lion ----------
replaceLine('canonFireGoldenLion', "  function canonFireGoldenLion(idx,die,target){const c=canonC(die),p=canonP(die),origin=dieTileLaunchPos(idx);die.canon.lionNext=die.canon.lionNext||'beam';if(die.canon.lionNext==='beam'){const dmg=c>=7?24:c>=5?22:c>=2?20:18,width=14*(1+(c>=2?.05:0)+(p>=7?.10:p>=3?.04:0)),hits=canonLineHits(origin,target,width);hits.forEach(e=>canonFireSimple(die,e,dmg*(p>=5?1.06:1),'special',{holy:1}));die.canon.lionNext='roar';fx('lionBeam',enemyRenderPos(target),{origin,width,dur:.5});}else{const king=(die.canon.kingCharge||0)>=5;if(king)die.canon.kingCharge=0;else die.canon.kingCharge=(die.canon.kingCharge||0)+1;const dmg=king?(c>=7?70:c>=6?62:c>=4?55:48):(c>=7?38:c>=5?34:c>=3?31:28),kingWidth=c>=7?4.25:c>=4?4.4:4,width=14*(king?kingWidth:c>=5?2.7:2.5)*(1+(p>=7?.10:p>=3?.04:0)),hits=canonLineHits(origin,target,width),kb=king?(c>=7?34:c>=6?28:22):(c>=7?20:c>=5?18:c>=3?15:12);hits.forEach(e=>{canonFireSimple(die,e,dmg*(p>=5?1.06:1)*(king&&p>=7?1.08:1),'special',{holy:1});canonKnockbackEnemy(e,kb);if(king&&c>=6)canonApplyStun(e,.4);});if(king){const dr=c>=7?.18:c>=6?.16:c>=4?.14:.12;state.board.forEach(d=>{if(d){d.buffs=d.buffs||[];d.buffs.push({type:'canonDR',amount:dr,t:2});}});}die.canon.lionNext='beam';fx('lionRoar',enemyRenderPos(target),{origin,width,king,dur:king?.85:.62});}}");

// ---------- Ace ----------
replaceLine('canonFireAce', "  function canonFireAce(die,target){const c=canonC(die),p=canonP(die),prog=progressFrac(target),form=prog<.30?'flat':prog<.65?'slice':'kick',base=c>=7?24:c>=5?22:c>=3?20:18,els=canonElementJewels(die),jBonus=els.length*.03,pip=p>=7?.05:p>=3?.02:0,baseChance=c>=3?.15:.12,hot=c>=6?(die.canon.hotHand||0):0,chance=Math.min(.60,baseChance+jBonus+pip+hot),heater=Math.random()<chance,airborne=!!target.lift;if(heater)die.canon.hotHand=0;else if(c>=6)die.canon.hotHand=Math.min(.20,(die.canon.hotHand||0)+.05);const ace=heater&&c>=7,hm=ace?1.85:c>=5?1.65:1.55,aff=heater&&els.length?Object.fromEntries([...new Set(els)].map(x=>[x,1/[...new Set(els)].length])):{};let main=form==='flat'?(c>=5?1.15:1.10):form==='kick'?(c>=5?1:.95):1;if(form==='kick'&&c>=4&&airborne)main*=1.10;if(heater)main*=hm;if(p>=5&&heater)main*=1.05;canonFireSimple(die,target,base*main,'physical',aff);if(form==='slice'){const search=50*(1+(p>=7?.15:p>=3?.05:0)),near=canonNearby(target,search),sec=ace?1:(c>=5?(heater?.95:.85):c>=2?(heater?.80:.75):.65);if(near[0])canonFireSimple(die,near[0],base*sec*(heater?hm:1),'physical',aff);if(ace&&near[1])canonFireSimple(die,near[1],base*.65*hm,'physical',aff);}if(form==='flat'){canonKnockbackEnemy(target,(c>=3?9:6)*(p>=5?1.08:1));if(heater){const burst=ace?.50:c>=5?.40:c>=3?.30:.20;canonNearby(target,ace?35:25).forEach(e=>canonFireSimple(die,e,base*burst,'physical',aff));if(ace){const behind=aliveEnemies().filter(e=>progressFrac(e)<progressFrac(target)).sort((a,b)=>progressFrac(b)-progressFrac(a))[0];if(behind)canonFireSimple(die,behind,base*.70*hm,'physical',aff);}}}if(form==='kick'){const kb=(ace?22:c>=4?14:10)*(p>=5?1.08:1);canonKnockbackEnemy(target,kb);let launch=ace?.75:c>=5?(heater?.60:.30):c>=4?(heater?.50:.30):(heater?.35:.20);if(!airborne&&Math.random()<launch&&!target.isBoss)startLift(target,'airborne',{rise:.18,hold:.12,fall:.35,height:(heater?30:24)*(p>=7?1.10:1),juggleable:true});if(ace)canonNearby(target,30*(p>=7?1.10:1)).forEach(e=>canonFireSimple(die,e,base*.35*hm,'physical',aff));}fx(form==='flat'?'aceFlat':form==='slice'?'aceSlice':'aceKick',enemyRenderPos(target),{heater,ace,dur:.5});}");

