replaceLine('canonFireBases', "  function canonFireBases(die,target){const c=canonC(die),p=canonP(die),base=c>=7?27:c>=5?24:c>=2?22:20,bases=die.canon.bases||0;if(bases>=3){die.canon.bases=0;const mult=c>=7?2.5:c>=5?2.3:2.2,origin=dieTileLaunchPos(state.board.indexOf(die)),aliveBefore=target.alive,line=canonLineHits(origin,target,28),radius=42*(1+(c>=7?.15:0)+(p>=5?.08:0)),shock=canonNearby(target,radius),zones=new Map();line.forEach(e=>zones.set(e,mult));shock.forEach(e=>zones.set(e,Math.max(zones.get(e)||0,c>=7?.50:.35)));zones.forEach((m,e)=>canonFireSimple(die,e,base*m*(p>=7?1.08:1),'physical',{}));line.forEach(e=>canonKnockbackEnemy(e,c>=7?28:22));if(c>=7&&target.alive)canonApplyStun(target,.5);if(c>=7&&aliveBefore&&!target.alive)die.canon.bases=1;fx('grandSlam',enemyRenderPos(target),{origin,radius,dur:.8});return;}let pressure=c>=6?[1,1.05,1.10,1.15][bases]:1,pinchChance=c>=4?.15:0;if(p>=7)pinchChance+=.05;else if(p>=3)pinchChance+=.02;pinchChance=Math.min(.20,pinchChance+canonInsight(die));let did=false;if(pinchChance&&Math.random()<pinchChance){const pm=c>=6?1.25:1.15;did=canonFireSimple(die,target,base*pm*pressure,'physical',{})>0;const nearby=canonNearby(target,30),sec=(c>=6?.75:.65)+(p>=5?.05:0);nearby.forEach(e=>{canonFireSimple(die,e,base*pm*sec,'physical',{});if(!e.isBoss)startLift(e,'airborne',{rise:.16,hold:.10,fall:.32,height:(c>=6?22:18)*(p>=7?1.1:1),juggleable:true});});if(!target.isBoss)startLift(target,'airborne',{rise:.18,hold:.16,fall:.38,height:(c>=6?33:28)*(p>=7?1.1:1),juggleable:true});fx('pinchHit',enemyRenderPos(target),{dur:.75});}else{let type='fast';if(c>=5){const r=Math.random();type=r<.25?'curve':r<.5?'change':'fast';}else if(c>=3&&Math.random()<.25)type='curve';if(type==='curve'){did=canonFireSimple(die,target,base*pressure,'physical',{})>0;const near=canonNearby(target,34)[0];if(near)canonFireSimple(die,near,base*(p>=3?.60:.55)*pressure,'physical',{});}else if(type==='change'){did=canonFireSimple(die,target,base*.95*pressure,'physical',{})>0;canonKnockbackEnemy(target,c>=5?12:8);canonApplyConfusion(target,(1+(p>=5?.15:0))*canonPotency(die));}else did=canonFireSimple(die,target,base*pressure,'physical',{});fx(type==='curve'?'baseCurve':type==='change'?'baseChange':'baseFast',enemyRenderPos(target),{dur:.4});}if(did)die.canon.bases=Math.min(3,bases+1);}");

